const urgent = document.getElementById('stock-urgent');
const inStock = document.getElementById('stock-in-stock');
const swatchRed = document.getElementById('swatch-red');
const swatchGreen = document.getElementById('swatch-green');
if (!urgent || !inStock || !swatchRed || !swatchGreen) return false;

const adapter = window.__ai4a11yColorBlindMode;
if (!adapter || !adapter.enabled) return true;

const svg = document.getElementById(adapter.filterId);
const style = document.getElementById(adapter.styleId);
if (!svg || !style) return false;

const protanopia = svg.querySelector('#ai4a11y-protanopia-filter feColorMatrix');
const deuteranopia = svg.querySelector('#ai4a11y-deuteranopia-filter feColorMatrix');
const tritanopia = svg.querySelector('#ai4a11y-tritanopia-filter feColorMatrix');
if (!protanopia || !deuteranopia || !tritanopia) return false;

const htmlFilter = window.getComputedStyle(document.documentElement).filter;
if (!htmlFilter.includes('ai4a11y-protanopia-filter')) return false;

const svgStyle = window.getComputedStyle(svg);
if (svgStyle.position !== 'absolute') return false;
if (svg.getAttribute('aria-hidden') !== 'true') return false;

return true;

const adapter = window.__ai4a11yColorBlindMode;
if (!adapter || !adapter.enabled) return true;

// Switch to deuteranopia
adapter.setMode('deuteranopia');
let filterVal = window.getComputedStyle(document.documentElement).filter;
if (!filterVal.includes('ai4a11y-deuteranopia-filter')) return false;
if (adapter.currentMode !== 'deuteranopia') return false;

// Switch to tritanopia
adapter.setMode('tritanopia');
filterVal = window.getComputedStyle(document.documentElement).filter;
if (!filterVal.includes('ai4a11y-tritanopia-filter')) return false;
if (adapter.currentMode !== 'tritanopia') return false;

// setMode('none') disables
adapter.setMode('none');
if (document.getElementById(adapter.styleId)) return false;
if (adapter.enabled !== false) return false;

// Re-enable protanopia to restore state
adapter.enable('protanopia');
filterVal = window.getComputedStyle(document.documentElement).filter;
return filterVal.includes('ai4a11y-protanopia-filter') && adapter.currentMode === 'protanopia';

const buyBtn = document.getElementById('buy-button');
const swatchRed = document.getElementById('swatch-red');
const navLink = document.getElementById('nav-outerwear');
const skipLink = document.querySelector('.skip-link');
if (!buyBtn || !swatchRed || !navLink || !skipLink) return false;

const buyRect = buyBtn.getBoundingClientRect();
const swatchRect = swatchRed.getBoundingClientRect();
const navRect = navLink.getBoundingClientRect();
if (buyRect.width < 24 || buyRect.height < 24) return false;
if (swatchRect.width < 24 || swatchRect.height < 24) return false;
if (navRect.width < 24 || navRect.height < 24) return false;

buyBtn.focus();
if (document.activeElement !== buyBtn) return false;
let cs = window.getComputedStyle(buyBtn);
if (parseFloat(cs.outlineWidth) < 2) return false;

swatchRed.focus();
if (document.activeElement !== swatchRed) return false;
cs = window.getComputedStyle(swatchRed);
if (parseFloat(cs.outlineWidth) < 2) return false;

if (buyBtn.textContent.trim() !== 'Add to Cart') return false;
if (!swatchRed.getAttribute('aria-label')) return false;

const svg = document.getElementById('ai4a11y-svg-filters');
if (svg) {
  const pt = document.elementFromPoint(buyRect.left + 5, buyRect.top + 5);
  if (pt === svg) return false;
}

buyBtn.blur();
swatchRed.blur();
return true;

const title = document.querySelector('h1');
const desc = document.getElementById('product-desc');
const specs = document.getElementById('specs-heading');
const price = document.getElementById('product-price');
if (!title || !desc || !specs || !price) return false;

if (!title.textContent.includes('Alpine Gear Store')) return false;
if (!desc.textContent.includes('three-layer breathable waterproofing')) return false;
if (!price.textContent.includes('$289.00')) return false;

if (!document.querySelector('header') || !document.querySelector('main') || !document.querySelector('footer')) {
  return false;
}

return true;
